window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/09_database_and_storage/02_types_of_data.md"] = [{"id":"content/09_database_and_storage/02_types_of_data.md:c0623953464b8493:1","question":"<p>В чем фундаментальная разница между OLTP и OLAP?</p>\n","answer":"<p><strong>Ответ:</strong> OLTP меняет небольшие наборы данных короткими транзакциями; OLAP агрегирует большие наборы. Сравнивать нужно profile запросов и SLA, а не только названия систем.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L1","line":26},{"id":"content/09_database_and_storage/02_types_of_data.md:228d656982bb6b69:1","question":"<p>Какие workload-характеристики у OLTP?</p>\n","answer":"<p><strong>Ответ:</strong> Много конкурентных коротких read/write, точечные индексы, ограничения и чувствительность к p99 commit. Важны конфликтность ключей и доля обновлений.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"L1","line":32},{"id":"content/09_database_and_storage/02_types_of_data.md:18e1903e092cf255:1","question":"<p>Какие workload-характеристики у OLAP?</p>\n","answer":"<p><strong>Ответ:</strong> Большие scan/join/group/sort, чтение избранных колонок и работа партиями. Скорость зависит от bandwidth, CPU, pruning и объёма промежуточных результатов.</p>\n<p><strong>Источник:</strong> <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L1","line":38},{"id":"content/09_database_and_storage/02_types_of_data.md:ac4b504100e018b8:1","question":"<p>Почему OLAP предпочитает column-store?</p>\n","answer":"<p><strong>Ответ:</strong> Считывает нужные столбцы, лучше сжимает однородные значения и обрабатывает batches SIMD. Восстановление полной строки и частые точечные изменения могут быть дороже.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L1","line":44},{"id":"content/09_database_and_storage/02_types_of_data.md:54921b79c1731cfe:1","question":"<p>Что такое transactional vs analytical query?</p>\n","answer":"<p><strong>Ответ:</strong> Транзакционный запрос читает/меняет операционный факт, аналитический обобщает множество фактов. Одно SQL-выражение может сочетать обе роли.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n<p><strong>[P]</strong></p>\n","group":"L1","line":50},{"id":"content/09_database_and_storage/02_types_of_data.md:a4dfc8ed9151c968:1","question":"<p>Смоделировать OLTP workload (много мелких writes)</p>\n","answer":"<p><strong>Ответ:</strong> Задать размер набора, распределение ключей, mix операций, threads и transaction size. Генерировать реалистичные конфликты, фиксировать seed, completed throughput, p50/p99 и ошибки.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L1","line":59},{"id":"content/09_database_and_storage/02_types_of_data.md:e6612db72a2d9f31:1","question":"<p>Смоделировать OLAP workload (scan + aggregation)</p>\n","answer":"<p><strong>Ответ:</strong> Подготовить данные больше/меньше RAM, выполнить scan нужных колонок с filter/group и проверить checksum результата. Отдельно измерить cold/warm run, прочитанные bytes и spill.</p>\n<p><strong>Источник:</strong> <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L1","line":65},{"id":"content/09_database_and_storage/02_types_of_data.md:c2a43b1a9b759f49:1","question":"<p>Написать benchmark (C++) для сравнения latency vs throughput</p>\n","answer":"<p><strong>Ответ:</strong> Использовать steady_clock и синхронный старт threads, не включать подготовку данных. Собрать распределение latency и завершённые ops/s; генератор open-loop должен учитывать coordinated omission.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a>; <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"L1","line":71},{"id":"content/09_database_and_storage/02_types_of_data.md:154609b514ae8721:1","question":"<p>Реализовать batched insert vs single insert</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить одинаковое число строк и одинаковую durability: по одному commit и batches разных размеров. Измерять не только rows/s, но и задержку строки, WAL bytes и память batch.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"L1","line":77},{"id":"content/09_database_and_storage/02_types_of_data.md:fbbf2d9e3b582c67:1","question":"<p>Сравнить performance row vs column layout</p>\n","answer":"<p><strong>Ответ:</strong> Создать одинаковые данные в AoS и SoA, сравнить point read всей строки и scan одного столбца. Проверить результат и bandwidth/cache misses при одинаковой компиляции и working set.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L1","line":83},{"id":"content/09_database_and_storage/02_types_of_data.md:71214b9edc71e277:1","question":"<p>Почему OLTP требует low latency, а OLAP — high throughput?</p>\n","answer":"<p><strong>Ответ:</strong> Операционные действия часто блокируют пользователя, аналитика обычно обрабатывает больше данных. Однако OLAP тоже имеет latency SLO, а OLTP — throughput capacity; это не взаимоисключающие требования.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a>; <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L2","line":96},{"id":"content/09_database_and_storage/02_types_of_data.md:2e108af7118a2751:1","question":"<p>Что такое star schema?</p>\n","answer":"<p><strong>Ответ:</strong> Факт-таблица с измерениями, присоединяемыми напрямую: звездообразная схема упрощает аналитические запросы. Гранулярность факта и ключи измерений должны быть явными.</p>\n<p><strong>Источник:</strong> <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L2","line":102},{"id":"content/09_database_and_storage/02_types_of_data.md:535d16c466f48c99:1","question":"<p>Что такое snowflake schema?</p>\n","answer":"<p><strong>Ответ:</strong> Нормализованные измерения образуют дополнительные уровни связей. Снижается часть дублирования, но увеличивается число JOIN и сложность запросов.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L2","line":108},{"id":"content/09_database_and_storage/02_types_of_data.md:bd26f39154c22e11:1","question":"<p>Почему joins в OLAP дорогие?</p>\n","answer":"<p><strong>Ответ:</strong> Затраты на чтение/build/probe hash tables, перераспределение и большой результат. JOIN не всегда дорог: фильтры, сортировка, индексы и небольшие измерения могут резко уменьшить стоимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"L2","line":114},{"id":"content/09_database_and_storage/02_types_of_data.md:622cc858f739e077:1","question":"<p>Что такое vectorized execution?</p>\n","answer":"<p><strong>Ответ:</strong> Оператор обрабатывает batch значений за вызов, уменьшая per-row overhead и облегчая SIMD. Vectorized execution не означает, что каждая операция использует аппаратный SIMD.</p>\n<pre><code>**Источник:** [Apache Arrow: Columnar format](https://arrow.apache.org/docs/format/Columnar.html)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L2","line":120},{"id":"content/09_database_and_storage/02_types_of_data.md:8323c10906b99e49:1","question":"<p>Реализовать column scan с SIMD</p>\n","answer":"<p><strong>Ответ:</strong> Обрабатывать фиксированные порции одинакового типа, сравнивать SIMD lanes, собирать mask и корректно обработать tail. Проверять CPU support/alignment и сравнивать с scalar oracle.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"L2","line":129},{"id":"content/09_database_and_storage/02_types_of_data.md:5c277dee1c16d6ae:1","question":"<p>Реализовать aggregation pipeline</p>\n","answer":"<p><strong>Ответ:</strong> Разделить filter→project→aggregate, хранить state по ключу группы и передавать batches. Ограничить память и определить spill/merge, NULL и overflow semantics.</p>\n<p><strong>Источник:</strong> <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L2","line":135},{"id":"content/09_database_and_storage/02_types_of_data.md:5a99ea392b553eaa:1","question":"<p>Написать простой vectorized executor</p>\n","answer":"<p><strong>Ответ:</strong> Ввести Batch с колонками и selection vector, операторы возвращают/потребляют batches. Убрать виртуальный вызов на строку, корректно завершать pipeline и проверять результат против scalar.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L2","line":141},{"id":"content/09_database_and_storage/02_types_of_data.md:2cef2b7af8733521:1","question":"<p>Реализовать batch processing</p>\n","answer":"<p><strong>Ответ:</strong> Ограничить размер batch и время накопления, обрабатывать whole/partial batches, корректно повторять сбой. End-to-end latency включает ожидание заполнения batch.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"L2","line":147},{"id":"content/09_database_and_storage/02_types_of_data.md:7ce5d174640ebe70:1","question":"<p>Реализовать simple columnar compression</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать RLE/dictionary/delta по данным, записывать codec metadata и bounds. Реализовать round-trip decoder и проверить случайные, пустые и предельные значения.</p>\n<pre><code>**Источник:** [Apache Parquet: File format](https://parquet.apache.org/docs/file-format/)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L2","line":153},{"id":"content/09_database_and_storage/02_types_of_data.md:f957dc74b9e0f3e6:1","question":"<p>Почему OLAP query грузит CPU на 100%?</p>\n","answer":"<p><strong>Ответ:</strong> Полный CPU может быть полезной vectorized обработкой, decompression, hashing или ошибочным plan. Проверить профили, bytes processed и итоговую скорость, отличить compute-bound от stalled cycles.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"L2","line":162},{"id":"content/09_database_and_storage/02_types_of_data.md:b8ae73e3356777a5:1","question":"<p>Почему OLTP latency нестабилен?</p>\n","answer":"<p><strong>Ответ:</strong> Lock waits, fsync/checkpoints, cache misses, pool queues и фоновые jobs меняют хвост. Сопоставить p99 с wait events и arrival rate, удерживая workload и durability постоянными.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/explicit-locking.html\">PostgreSQL: Explicit locking</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"L2","line":168},{"id":"content/09_database_and_storage/02_types_of_data.md:721161076d2ea41c:1","question":"<p>Почему scan быстрее index lookup?</p>\n","answer":"<p><strong>Ответ:</strong> При большой селективности последовательное чтение дешевле множества случайных обращений по индексу. Проверить фактическую долю строк, cache state, clustering и planner estimates.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"L2","line":174},{"id":"content/09_database_and_storage/02_types_of_data.md:4b22877946461475:1","question":"<p>Почему cache misses критичны для OLAP?</p>\n","answer":"<p><strong>Ответ:</strong> Scan должен быстро подавать значения вычислительным блокам; лишние cache lines снижают эффективный bandwidth. Проверить выбранные поля, layout и промежуточные объекты.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L2","line":180},{"id":"content/09_database_and_storage/02_types_of_data.md:1bf84aa2470f08c8:1","question":"<p>Почему branch misprediction влияет на OLAP?</p>\n","answer":"<p><strong>Ответ:</strong> Непредсказуемый branch на каждую строку сбрасывает pipeline. Selection masks/SIMD могут помогать, но проверять по данным и compiler output: branchless не всегда быстрее.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L2","line":186},{"id":"content/09_database_and_storage/02_types_of_data.md:200980e0bad35b03:1","question":"<p>Как устроен execution engine в аналитических БД?</p>\n","answer":"<p><strong>Ответ:</strong> Pipeline scan/filter/project и blocking stages sort/hash aggregation, работающие над batches. Планировщик выбирает параллелизм, память и spill; профиль показывает затраты каждого оператора.</p>\n<p><strong>Источник:</strong> <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"L3","line":199},{"id":"content/09_database_and_storage/02_types_of_data.md:3b60773d1a129004:1","question":"<p>Что такое late materialization?</p>\n","answer":"<p><strong>Ответ:</strong> Откладывание сборки полных строк до фильтрации/агрегации. Переносятся IDs/selection vectors и только нужные столбцы, уменьшая bytes и allocation.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":205},{"id":"content/09_database_and_storage/02_types_of_data.md:b2e82777227c870c:1","question":"<p>Что такое predicate pushdown?</p>\n","answer":"<p><strong>Ответ:</strong> Безопасный перенос фильтра ближе к scan/source, чтобы сократить downstream rows/bytes. Не все выражения можно переносить через outer join, aggregation или volatile функции.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"L3","line":211},{"id":"content/09_database_and_storage/02_types_of_data.md:c9b5f2c12add4816:1","question":"<p>Как работает SIMD в аналитике?</p>\n","answer":"<p><strong>Ответ:</strong> Одна инструкция применяет операцию к нескольким значениям одного типа. Выигрыш ограничивают память, ветвления, типы и преобразования; нужен scalar fallback.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"L3","line":217},{"id":"content/09_database_and_storage/02_types_of_data.md:2f1bde5e723d78d8:1","question":"<p>Что такое pipeline execution?</p>\n","answer":"<p><strong>Ответ:</strong> Смежные неблокирующие операторы передают данные без материализации полного промежуточного результата. Sort/global aggregation могут создавать pipeline barriers.</p>\n<pre><code>**Источник:** [ClickHouse: Introduction](https://clickhouse.com/docs/get-started/about/intro)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L3","line":223},{"id":"content/09_database_and_storage/02_types_of_data.md:6ba845eaffac22bb:1","question":"<p>Реализовать predicate pushdown</p>\n","answer":"<p><strong>Ответ:</strong> Представить predicate в scan API, применять до создания полного Row и подтвердить уменьшение rows read/materialized. Перенос разрешать только при сохранении SQL semantics.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"L3","line":232},{"id":"content/09_database_and_storage/02_types_of_data.md:1313ef1fb9a1fb67:1","question":"<p>Реализовать late materialization</p>\n","answer":"<p><strong>Ответ:</strong> Хранить отобранные row IDs, затем загрузить требуемые столбцы только для survivors. Сравнить с eager reconstruction на низкой/высокой селективности.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L3","line":238},{"id":"content/09_database_and_storage/02_types_of_data.md:c85144f8392eb835:1","question":"<p>Написать SIMD filter (AVX)</p>\n","answer":"<p><strong>Ответ:</strong> Проверять AVX/AVX2 поддержку, vector width, mask и tail; не читать за границы массива. Сравнить бит-в-бит с scalar filter и измерять одинаковый input.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L3","line":244},{"id":"content/09_database_and_storage/02_types_of_data.md:2fc9286ff559c1c5:1","question":"<p>Реализовать columnar iterator</p>\n","answer":"<p><strong>Ответ:</strong> Итератор выдаёт contiguous typed spans/blocks и validity bitmap. Сохранить lifetime backing storage, корректный переход через chunk и NULL semantics.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L3","line":250},{"id":"content/09_database_and_storage/02_types_of_data.md:5b7fc58e4531aeb6:1","question":"<p>Реализовать pipeline execution engine</p>\n","answer":"<p><strong>Ответ:</strong> Описать операторный DAG, batches, scheduling и backpressure. Blocking stages материализуют/сливают state, cancellation закрывает ресурсы и не теряет ошибки.</p>\n<pre><code>**Источник:** [ClickHouse: Introduction](https://clickhouse.com/docs/get-started/about/intro); [Google SRE: Handling Overload](https://sre.google/sre-book/handling-overload/)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L3","line":256},{"id":"content/09_database_and_storage/02_types_of_data.md:121614cd05749254:1","question":"<p>Как найти bottleneck в аналитическом запросе?</p>\n","answer":"<p><strong>Ответ:</strong> EXPLAIN с фактическими строками плюс профили CPU/I/O/memory/network. Искать ошибки cardinality, skew, spills и dominant stage вместо оптимизации самого длинного SQL-фрагмента.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":265},{"id":"content/09_database_and_storage/02_types_of_data.md:cf2997e158f8a3a4:1","question":"<p>Почему memory bandwidth становится лимитом?</p>\n","answer":"<p><strong>Ответ:</strong> Scan потребляет больше байтов, чем память успевает доставить CPU. Измерить bandwidth и stalled cycles; уменьшить columns/width/материализацию и проверить NUMA.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a></p>\n","group":"L3","line":271},{"id":"content/09_database_and_storage/02_types_of_data.md:028f3dae3ffb58aa:1","question":"<p>Как диагностировать NUMA penalty?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить размещение threads/pages, local/remote traffic и производительность pinned к локальному узлу. Высокий remote access может быть следствием first-touch в одном loader thread.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a></p>\n","group":"L3","line":277},{"id":"content/09_database_and_storage/02_types_of_data.md:06a43e26f4e68812:1","question":"<p>Почему prefetching не работает?</p>\n","answer":"<p><strong>Ответ:</strong> Random access, нерегулярный stride, слишком далёкий/близкий prefetch и насыщение bandwidth скрывают пользу. Сравнить hardware/software prefetch и не добавлять лишние reads в cache.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":283},{"id":"content/09_database_and_storage/02_types_of_data.md:3bd2c1c4469f6163:1","question":"<p>Как найти vectorization regression?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить compiler vectorization reports, assembly, типы/alignment и число scalar fallback. Проверить thresholds/selectivity и тот же CPU: иной input может менять branch behaviour без code regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":289},{"id":"content/09_database_and_storage/02_types_of_data.md:ba3669ffcca858c7:1","question":"<p>Когда разделять OLTP и OLAP системы?</p>\n","answer":"<p><strong>Ответ:</strong> Когда аналитические scan/CPU/I/O мешают latency транзакций либо нужны другие форматы/retention. Доставлять изменения через CDC с измеримой freshness и reconciliation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/logical-replication.html\">PostgreSQL: Logical replication</a>; <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L4","line":302},{"id":"content/09_database_and_storage/02_types_of_data.md:85185fd726a588d3:1","question":"<p>Как строить HTAP систему?</p>\n","answer":"<p><strong>Ответ:</strong> Поддерживать transactional row path и аналитическую проекцию/snapshot с определённым lag. Изолировать ресурсы, определить consistency аналитики и стоимость propagation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L4","line":308},{"id":"content/09_database_and_storage/02_types_of_data.md:d4acd4e6d3c2b740:1","question":"<p>Как проектировать real-time analytics?</p>\n","answer":"<p><strong>Ответ:</strong> Durable ingestion → partitioned stream → windowed aggregation → serving storage. Задать freshness SLO, event time, late events, replay и идемпотентные обновления.</p>\n<p><strong>Источник:</strong> <a href=\"https://kafka.apache.org/41/streams/core-concepts/\">Apache Kafka Streams: Concepts</a>; <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"L4","line":314},{"id":"content/09_database_and_storage/02_types_of_data.md:5dee23a680edd616:1","question":"<p>Как минимизировать data duplication?</p>\n","answer":"<p><strong>Ответ:</strong> Хранить один canonical source, производные проекции только под измеренные запросы, общие objects/форматы и lifecycle. Дублирование иногда необходимо для latency/изоляции; цена синхронизации должна быть явной.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/logical-replication.html\">PostgreSQL: Logical replication</a>; <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L4","line":320},{"id":"content/09_database_and_storage/02_types_of_data.md:c6abcea0c1051f43:1","question":"<p>Как выбрать storage layout под mixed workload?</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать доминирующий путь; для точечных изменений row store, для scan column store, для mixed — раздельные проекции либо hybrid. Сравнивать полный workload с concurrency и maintenance.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"L4","line":326},{"id":"content/09_database_and_storage/02_types_of_data.md:0b9f75498bd580be:1","question":"<p>В чем разница row-store vs column-store?</p>\n","answer":"<p><strong>Ответ:</strong> Row store размещает поля строки рядом, column store — значения столбца. Первый удобен для целой записи, второй уменьшает чтение ненужных полей и улучшает сжатие.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L1","line":343},{"id":"content/09_database_and_storage/02_types_of_data.md:1341069efc469132:1","question":"<p>Когда лучше row-based?</p>\n","answer":"<p><strong>Ответ:</strong> Для point reads целой записи, коротких транзакций и частых обновлений. Индексы и buffer cache всё равно определяют фактическую скорость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"L1","line":349},{"id":"content/09_database_and_storage/02_types_of_data.md:2e134584e0adb485:1","question":"<p>Когда лучше column-based?</p>\n","answer":"<p><strong>Ответ:</strong> Для scan небольшого числа колонок, агрегаций и сжатия больших массивов. Оценить цену updates/deletes и реконструкции строк.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://clickhouse.com/docs/get-started/about/intro\">ClickHouse: Introduction</a></p>\n","group":"L1","line":355},{"id":"content/09_database_and_storage/02_types_of_data.md:e09e9e2bfb779515:1","question":"<p>Что такое cache locality?</p>\n","answer":"<p><strong>Ответ:</strong> Temporal locality — повторное использование недавно прочитанного, spatial — использование соседних bytes/cache lines. Layout и working set определяют попадание в cache.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/kernel-hacking/false-sharing.html\">Linux kernel: False sharing</a></p>\n","group":"L1","line":361},{"id":"content/09_database_and_storage/02_types_of_data.md:14fee17724fa002c:1","question":"<p>Почему column-store лучше для агрегаций?</p>\n","answer":"<p><strong>Ответ:</strong> Однородные contiguous значения лучше сжимаются и обрабатываются без чтения остальных полей. Выигрыш уменьшается при запросах почти всех колонок и точечном доступе.</p>\n<pre><code>**Источник:** [Apache Arrow: Columnar format](https://arrow.apache.org/docs/format/Columnar.html)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L1","line":367},{"id":"content/09_database_and_storage/02_types_of_data.md:487144a73c9b4afb:1","question":"<p>Реализовать row layout (struct of structs)</p>\n","answer":"<p><strong>Ответ:</strong> Создать vector&lt;Row&gt; с фиксированными полями; контролировать padding и lifetime. Для persistence сериализовать формат отдельно от C++ object representation.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"L1","line":376},{"id":"content/09_database_and_storage/02_types_of_data.md:ae750313392ffb95:1","question":"<p>Реализовать column layout (struct of arrays)</p>\n","answer":"<p><strong>Ответ:</strong> Создать отдельные vector&lt;T&gt; на поле и общий row count; синхронно менять длины и validity. Для чтения строки собирать одинаковый индекс из всех колонок.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"L1","line":382},{"id":"content/09_database_and_storage/02_types_of_data.md:d32769e0d5e5680d:1","question":"<p>Сравнить cache misses</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить AoS/SoA на одинаковых данных и operations, собрать cache misses/cycles/bytes. Учитывать hardware prefetch и повторное использование между проходами.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L1","line":388},{"id":"content/09_database_and_storage/02_types_of_data.md:2b2c16fb82c58083:1","question":"<p>Написать scan benchmark</p>\n","answer":"<p><strong>Ответ:</strong> Исключить setup, выполнить warmup и замеры по рабочим наборам до/сверх LLC/RAM. Проверять checksum результата, чтобы compiler не удалил loop.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"L1","line":394},{"id":"content/09_database_and_storage/02_types_of_data.md:22058943e777ea37:1","question":"<p>Реализовать simple filter</p>\n","answer":"<p><strong>Ответ:</strong> Скалярный loop проверяет predicate и пишет selection IDs либо агрегат. Корректно обрабатывать NULL, пустой input и overflow результата.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a>; <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"L1","line":400},{"id":"content/09_database_and_storage/02_types_of_data.md:a5578989b23d8cef:1","question":"<p>Что такое compression в column-store?</p>\n","answer":"<p><strong>Ответ:</strong> Однородные последовательности кодируются дешевле: dictionary, RLE, delta и bit-packing. Encoding и compression codec — разные этапы.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L2","line":413},{"id":"content/09_database_and_storage/02_types_of_data.md:05f293a210eb1198:1","question":"<p>Что такое dictionary encoding?</p>\n","answer":"<p><strong>Ответ:</strong> Словарь уникальных значений и массив компактных IDs. Хорош для низкой кардинальности; для произвольного сравнения учитывать порядок/семантику словаря.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L2","line":419},{"id":"content/09_database_and_storage/02_types_of_data.md:5a62aca738464d81:1","question":"<p>Что такое run-length encoding?</p>\n","answer":"<p><strong>Ответ:</strong> Серия одинаковых значений кодируется парой value/count. Случайные данные могут стать больше; длины проверяются при decode.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L2","line":425},{"id":"content/09_database_and_storage/02_types_of_data.md:607aaf9251116d34:1","question":"<p>Что такое bit-packing?</p>\n","answer":"<p><strong>Ответ:</strong> Значения фиксированной ограниченной разрядности упаковываются без выравнивания по целым машинным словам. Нужны bounds, безопасные сдвиги и корректный cross-word decode.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L2","line":431},{"id":"content/09_database_and_storage/02_types_of_data.md:226292cb0f14208a:1","question":"<p>Почему column-store лучше с SIMD?</p>\n","answer":"<p><strong>Ответ:</strong> Колонки имеют одинаковый тип и contiguous данные, что уменьшает gather и преобразования. NULL bitmap и variable-length значения требуют дополнительных masks/offsets.</p>\n<pre><code>**Источник:** [Apache Arrow: Columnar format](https://arrow.apache.org/docs/format/Columnar.html)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L2","line":437},{"id":"content/09_database_and_storage/02_types_of_data.md:49f030fb9c030918:1","question":"<p>Реализовать dictionary encoding</p>\n","answer":"<p><strong>Ответ:</strong> Построить value→ID map и обратный dictionary, encode IDs минимальной ширины. Decode и сравнение должны учитывать NULL и неизвестные значения.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L2","line":446},{"id":"content/09_database_and_storage/02_types_of_data.md:170f6f9ce644dece:1","question":"<p>Реализовать RLE</p>\n","answer":"<p><strong>Ответ:</strong> Считать длину текущего run, emit при смене, обработать последний run и count overflow. Проверить round-trip на чередующихся/повторяющихся/пустых данных.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L2","line":452},{"id":"content/09_database_and_storage/02_types_of_data.md:be645817083b9b8a:1","question":"<p>Реализовать bit-packing</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать bit width по диапазону, записывать/читать через проверенные маски и сдвиги, не сдвигать на ширину слова. Хранить число значений и валидировать размер buffer.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a>; <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"L2","line":458},{"id":"content/09_database_and_storage/02_types_of_data.md:21cfab69bd01c943:1","question":"<p>Реализовать vectorized scan</p>\n","answer":"<p><strong>Ответ:</strong> Работать batches фиксированного типа и mask, отдельно validity и tail. Измерить SIMD и scalar на memory/compute-bound вариантах.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L2","line":464},{"id":"content/09_database_and_storage/02_types_of_data.md:91f5997fcac48156:1","question":"<p>Реализовать selective column loading</p>\n","answer":"<p><strong>Ответ:</strong> Получить набор требуемых колонок из projection/filter, читать только их chunks. Не исключать столбец, используемый скрытым predicate/join/order.</p>\n<pre><code>**Источник:** [Apache Parquet: File format](https://parquet.apache.org/docs/file-format/)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L2","line":470},{"id":"content/09_database_and_storage/02_types_of_data.md:f809449a6bd301f7:1","question":"<p>Почему column-store медленный для point lookup?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс может найти row ID быстро, но затем нужны чтение/decode нескольких колонок/блоков. Холодные wide point lookups часто платят лишним I/O и reconstruction.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L2","line":479},{"id":"content/09_database_and_storage/02_types_of_data.md:927b2dac11e53eb1:1","question":"<p>Почему row-store плохо масштабируется для аналитики?</p>\n","answer":"<p><strong>Ответ:</strong> Читаются ненужные поля, хуже сжатие нужной колонки, больше cache/IO. Покрывающий индекс и projection могут уменьшить разницу, поэтому измерять конкретный запрос.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L2","line":485},{"id":"content/09_database_and_storage/02_types_of_data.md:daf3a8ebd9ba6541:1","question":"<p>Почему compression ухудшает latency?</p>\n","answer":"<p><strong>Ответ:</strong> Декомпрессия добавляет CPU и может требовать целый block ради одного значения. Проверить codec, block size, lookup pattern и cache decoded blocks.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L2","line":491},{"id":"content/09_database_and_storage/02_types_of_data.md:8f936b961f35e635:1","question":"<p>Почему CPU cache thrashing?</p>\n","answer":"<p><strong>Ответ:</strong> Working set/associativity, конкурирующие threads или большие промежуточные данные вытесняют полезные lines. Профилировать LLC misses и footprint, уменьшить data movement.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/kernel-hacking/false-sharing.html\">Linux kernel: False sharing</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L2","line":497},{"id":"content/09_database_and_storage/02_types_of_data.md:ce808b151e124ccc:1","question":"<p>Почему memory alignment влияет на perf?</p>\n","answer":"<p><strong>Ответ:</strong> Misaligned accesses могут пересекать cache lines/pages; некоторые инструкции требуют alignment. Современные unaligned loads не всегда медленнее, поэтому нужны assembly и замер.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"L2","line":503},{"id":"content/09_database_and_storage/02_types_of_data.md:c3cac2a59f2ecb5d:1","question":"<p>Что такое hybrid storage (PAX, DSM)?</p>\n","answer":"<p><strong>Ответ:</strong> DSM разделяет атрибуты по колонкам; PAX группирует мини-колонки внутри страницы. PAX сохраняет page locality строк, улучшая обработку выбранных полей в странице.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":516},{"id":"content/09_database_and_storage/02_types_of_data.md:ef6ffdac9caf287f:1","question":"<p>Как устроен Apache Parquet / ORC?</p>\n","answer":"<p><strong>Ответ:</strong> Колонночные форматы с row groups/stripes, column chunks, pages, encodings и metadata для pruning. Конкретная организация Parquet и ORC различается; это форматы, а не полноценные БД.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":522},{"id":"content/09_database_and_storage/02_types_of_data.md:6f793e96c8c928c3:1","question":"<p>Что такое column chunk?</p>\n","answer":"<p><strong>Ответ:</strong> Набор страниц одной колонки внутри row group Parquet. Имеет metadata/encoding/compression и позволяет читать выбранный столбец.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":528},{"id":"content/09_database_and_storage/02_types_of_data.md:24fffbe4f5acbff3:1","question":"<p>Что такое encoding pipelines?</p>\n","answer":"<p><strong>Ответ:</strong> Последовательность представления значений: dictionary/delta/RLE/bit-packing, затем общий codec. Decoder должен знать порядок, версии и параметры каждого шага.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":534},{"id":"content/09_database_and_storage/02_types_of_data.md:d5db62577f1cacd1:1","question":"<p>Как работает predicate pushdown в column store?</p>\n","answer":"<p><strong>Ответ:</strong> Использует min/max/statistics или фильтры для пропуска chunks/pages и применяет predicate при decode. Нельзя пропустить блок, если metadata недостаточно для доказательства отсутствия совпадений.</p>\n<pre><code>**Источник:** [Apache Parquet: File format](https://parquet.apache.org/docs/file-format/)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L3","line":540},{"id":"content/09_database_and_storage/02_types_of_data.md:77358bef2040cb23:1","question":"<p>Реализовать PAX layout</p>\n","answer":"<p><strong>Ответ:</strong> Внутри page выделить секции колонок с offsets/validity и общим числом строк. Проверять capacity при insert, перенос значений и реконструкцию row.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"L3","line":549},{"id":"content/09_database_and_storage/02_types_of_data.md:f59dc6e53e087b72:1","question":"<p>Реализовать column chunk storage</p>\n","answer":"<p><strong>Ответ:</strong> Записать typed blocks, validity, offsets, metadata и checksum, затем footer/index. Сначала завершить chunk, затем публиковать его в manifest; parser проверяет границы.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":555},{"id":"content/09_database_and_storage/02_types_of_data.md:6ba845eaffac22bb:2","question":"<p>Реализовать predicate pushdown</p>\n","answer":"<p><strong>Ответ:</strong> По metadata отсеять только доказанно неподходящие row groups, затем фильтровать decoded values. Сравнить результат со full scan, включая NULL и граничные значения.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":561},{"id":"content/09_database_and_storage/02_types_of_data.md:a38c9f4cc1b4e54a:1","question":"<p>Реализовать selective decompression</p>\n","answer":"<p><strong>Ответ:</strong> Применить pruning на metadata и читать/decode только нужные pages колонок. Минимальная единица декомпрессии задаётся codec/page, а не одним row ID.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L3","line":567},{"id":"content/09_database_and_storage/02_types_of_data.md:2cd90998faef96cf:1","question":"<p>Реализовать column pruning</p>\n","answer":"<p><strong>Ответ:</strong> Вычислить требуемые field IDs из всего plan и не открывать остальные chunks. Учитывать predicate, sort, join и hidden schema dependencies.</p>\n<pre><code>**Источник:** [Apache Parquet: File format](https://parquet.apache.org/docs/file-format/)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L3","line":573},{"id":"content/09_database_and_storage/02_types_of_data.md:9c97dc158f740dd6:1","question":"<p>Почему decompression bottleneck?</p>\n","answer":"<p><strong>Ответ:</strong> Определить долю CPU codec в профиле и bytes decoded/returned. Изменить codec/block size, применять pruning/cache и оценить trade-off с I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":582},{"id":"content/09_database_and_storage/02_types_of_data.md:c117d51062a141d0:1","question":"<p>Почему IO pattern стал случайным?</p>\n","answer":"<p><strong>Ответ:</strong> Selective reads множества scattered chunks и late materialization превращают scan в random access. Проверить row group size, сортировку данных, coalescing и план.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"L3","line":588},{"id":"content/09_database_and_storage/02_types_of_data.md:65c870d406a676e0:1","question":"<p>Почему vectorization не даёт прироста?</p>\n","answer":"<p><strong>Ответ:</strong> Memory bandwidth, маленькие batches, branches, conversion, gather и scalar tail ограничивают SIMD. Сравнить instructions/row и bytes/row, не только наличие AVX в assembly.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":594},{"id":"content/09_database_and_storage/02_types_of_data.md:01813b8d6b8a5969:1","question":"<p>Как диагностировать misaligned loads?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить адреса/stride и инструкции, долю split-line/page accesses. Сравнить aligned/unaligned buffers при равном input и исключить чтение за границы.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":600},{"id":"content/09_database_and_storage/02_types_of_data.md:711fbcaa9fed0d44:1","question":"<p>Почему page faults растут при scan?</p>\n","answer":"<p><strong>Ответ:</strong> Scan впервые затрагивает mapped pages либо RAM не хватает. Minor faults и major I/O различны; проверить pressure/swap, readahead и размер рабочего набора.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/mmap.2.html\">Linux man-pages: mmap</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":606},{"id":"content/09_database_and_storage/02_types_of_data.md:0d63808f3d48497f:1","question":"<p>Как выбрать layout для mixed workload?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить стоимость whole-row point access, updates и projection scans. Hybrid/две проекции оправданы, когда выигрыш превышает maintenance и допустим lag.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.postgresql.org/docs/current/logical-replication.html\">PostgreSQL: Logical replication</a></p>\n","group":"L4","line":619},{"id":"content/09_database_and_storage/02_types_of_data.md:fd13a30bb014efa7:1","question":"<p>Когда использовать hybrid storage?</p>\n","answer":"<p><strong>Ответ:</strong> Если один layout не обслуживает критичные point и scan SLO, а дополнительная синхронизация/хранение приемлемы. Сначала проверить простой row-store с индексами.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"L4","line":625},{"id":"content/09_database_and_storage/02_types_of_data.md:f8416127d3838548:1","question":"<p>Как проектировать column-store engine?</p>\n","answer":"<p><strong>Ответ:</strong> Schema/types → immutable column chunks → metadata/pruning → vectorized execution → update/delete visibility. Определить WAL/recovery, compaction и snapshot semantics, а не только формат файла.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a>; <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a></p>\n","group":"L4","line":631},{"id":"content/09_database_and_storage/02_types_of_data.md:1d0d352287d4ab15:1","question":"<p>Как выбрать encoding strategy?</p>\n","answer":"<p><strong>Ответ:</strong> По cardinality, runs, диапазонам и query path выбирать dictionary/RLE/delta/bitpack. Решение принимать per column/chunk и поддерживать fallback на plain encoding.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"L4","line":637},{"id":"content/09_database_and_storage/02_types_of_data.md:a1daa2ce81d89f34:1","question":"<p>Как оптимизировать под SSD vs RAM?</p>\n","answer":"<p><strong>Ответ:</strong> В RAM важны bytes moved, cache и NUMA; на SSD также IOPS, read size и endurance. Холодные и прогретые queries оценивать отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L4","line":643},{"id":"content/09_database_and_storage/02_types_of_data.md:363129dbb230d70a:1","question":"<p>Что такое in-memory DB?</p>\n","answer":"<p><strong>Ответ:</strong> БД, чей основной рабочий набор обрабатывается в памяти. Может иметь durable журнал/snapshots; «in-memory» не означает отсутствие диска.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a>; <a href=\"https://github.com/facebook/rocksdb/wiki/RocksDB-Overview\">RocksDB: Overview</a></p>\n","group":"L1","line":660},{"id":"content/09_database_and_storage/02_types_of_data.md:af5b9518805dc532:1","question":"<p>Почему RAM быстрее диска?</p>\n","answer":"<p><strong>Ответ:</strong> У RAM нет файлового/блочного пути и задержек flash/controller; доступ значительно короче. Однако cache/NUMA/случайный доступ всё равно важны, а RAM обычно volatile.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a></p>\n","group":"L1","line":666},{"id":"content/09_database_and_storage/02_types_of_data.md:1aa77590e66fa715:1","question":"<p>Что такое persistence в in-memory DB?</p>\n","answer":"<p><strong>Ответ:</strong> Механизм восстановления state после перезапуска: snapshots, журнал и/или устойчивые реплики. Подтверждение commit и окно возможной потери задаются конфигурацией.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"L1","line":672},{"id":"content/09_database_and_storage/02_types_of_data.md:565252f22d4b77e6:1","question":"<p>Что такое snapshot?</p>\n","answer":"<p><strong>Ответ:</strong> Согласованная копия состояния в определённый момент/sequence. Нужно обеспечить целостность во время копирования и atomic publication завершённой копии.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a>; <a href=\"https://www.postgresql.org/docs/current/backup.html\">PostgreSQL: Backup and restore</a></p>\n","group":"L1","line":678},{"id":"content/09_database_and_storage/02_types_of_data.md:8ad4cc9fb7972f1e:1","question":"<p>Что такое durability trade-off?</p>\n","answer":"<p><strong>Ответ:</strong> Частый sync уменьшает окно потери, но добавляет latency/I/O; периодический sync допускает потерю последних ACK при crash. Условие должно быть явным и проверенным.</p>\n<pre><code>**Источник:** [Linux man-pages: fsync](https://man7.org/linux/man-pages/man2/fsync.2.html); [PostgreSQL: Write-Ahead Logging](https://www.postgresql.org/docs/current/wal-intro.html)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L1","line":684},{"id":"content/09_database_and_storage/02_types_of_data.md:4d3294ca74c312e1:1","question":"<p>Реализовать in-memory KV store</p>\n","answer":"<p><strong>Ответ:</strong> Hash map с get/put/delete и явной моделью concurrency; добавить bounds, errors и lifetime. Durability и transactions — отдельные подсистемы, не свойства unordered_map.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/unord.req\">C++ working draft: Unordered associative containers</a>; <a href=\"https://15445.courses.cs.cmu.edu/fall2024/notes/07-hashtables.pdf\">CMU 15-445: Hash tables</a></p>\n","group":"L1","line":693},{"id":"content/09_database_and_storage/02_types_of_data.md:e39f2d3d8c058ef4:1","question":"<p>Реализовать snapshot на диск</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать snapshot/версии, записать во временный файл, проверить checksum и atomically publish. Для rename durability может требоваться sync directory; не перезаписывать единственную исправную копию.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/backup.html\">PostgreSQL: Backup and restore</a>; <a href=\"https://man7.org/linux/man-pages/man2/fsync.2.html\">Linux man-pages: fsync</a></p>\n","group":"L1","line":699},{"id":"content/09_database_and_storage/02_types_of_data.md:fedb36fcaba2a71f:1","question":"<p>Использовать mmap</p>\n","answer":"<p><strong>Ответ:</strong> Отображать файл с корректным размером/permissions, проверять MAP_FAILED и границы. MAP_SHARED не даёт транзакционность и не означает durable ACK без протокола sync/recovery.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/mmap.2.html\">Linux man-pages: mmap</a>; <a href=\"https://man7.org/linux/man-pages/man2/fsync.2.html\">Linux man-pages: fsync</a></p>\n","group":"L1","line":705},{"id":"content/09_database_and_storage/02_types_of_data.md:0cfd100d4d04f8ff:1","question":"<p>Реализовать ring buffer для WAL</p>\n","answer":"<p><strong>Ответ:</strong> Ring с monotonic positions, publish после полного record, reuse после durable watermark. При заполнении block/backpressure; нельзя перезаписывать ещё не сохранённый WAL.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://eel.is/c++draft/atomics\">C++ working draft: Atomics</a></p>\n","group":"L1","line":711},{"id":"content/09_database_and_storage/02_types_of_data.md:0beae41d769826ca:1","question":"<p>Реализовать простой allocator</p>\n","answer":"<p><strong>Ответ:</strong> Pool фиксированного размера с free list и alignment, fallback на upstream allocation. Ownership/lifetime и concurrency определить заранее; тестировать double-free и exhaustion.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/mem.res\">C++ working draft: Memory resources</a></p>\n","group":"L1","line":717},{"id":"content/09_database_and_storage/02_types_of_data.md:876ce1b5f48632c7:1","question":"<p>Что такое NUMA?</p>\n","answer":"<p><strong>Ответ:</strong> Неравномерная стоимость памяти по CPU/socket: local быстрее remote. Размещать обработчик и его страницы совместно, учитывая баланс узлов.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a></p>\n","group":"L2","line":730},{"id":"content/09_database_and_storage/02_types_of_data.md:1aeaa8b8b4a7fc28:1","question":"<p>Почему memory latency важна?</p>\n","answer":"<p><strong>Ответ:</strong> In-memory workload может упираться в зависимые cache misses и pointer chasing, а не CPU instructions. Измерять stalled cycles, locality и размер working set.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://docs.kernel.org/kernel-hacking/false-sharing.html\">Linux kernel: False sharing</a></p>\n","group":"L2","line":736},{"id":"content/09_database_and_storage/02_types_of_data.md:b713a0d1156f502a:1","question":"<p>Что такое lock-free структуры?</p>\n","answer":"<p><strong>Ответ:</strong> Гарантируют системный прогресс без обязательного ожидания mutex; не равны wait-free и могут проигрывать при конкуренции. Требуют memory ordering и безопасного reclamation.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/atomics\">C++ working draft: Atomics</a></p>\n","group":"L2","line":742},{"id":"content/09_database_and_storage/02_types_of_data.md:7836d30ad5ce9744:1","question":"<p>Что такое false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Независимые threads пишут разные поля одной cache line, вызывая invalidation/bouncing. Padding/разделение помогает, но увеличивает footprint.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/kernel-hacking/false-sharing.html\">Linux kernel: False sharing</a></p>\n","group":"L2","line":748},{"id":"content/09_database_and_storage/02_types_of_data.md:5caf315219059791:1","question":"<p>Что такое memory fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Свободная память распределена так, что её нельзя эффективно использовать, либо allocator удерживает arenas. Различать internal/external fragmentation и leak.</p>\n<pre><code> **Источник:** [C++ working draft: Memory resources](https://eel.is/c++draft/mem.res)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L2","line":754},{"id":"content/09_database_and_storage/02_types_of_data.md:ffc10009d98eb1d2:1","question":"<p>Реализовать lock-free queue</p>\n","answer":"<p><strong>Ответ:</strong> Для SPSC использовать bounded ring: producer/consumer indices с release/acquire и явно обработанным full/empty. MPMC существенно сложнее; брать доказанный алгоритм и решать reclamation.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/atomics\">C++ working draft: Atomics</a></p>\n","group":"L2","line":763},{"id":"content/09_database_and_storage/02_types_of_data.md:837a6ac78f595060:1","question":"<p>Реализовать custom allocator</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать arena/slab под реальные размеры и lifetime, соблюдать alignment и освобождение через тот же resource. Не скрывать нехватку памяти и thread-safety assumptions.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/mem.res\">C++ working draft: Memory resources</a></p>\n","group":"L2","line":769},{"id":"content/09_database_and_storage/02_types_of_data.md:65887f51236f41e3:1","question":"<p>Оптимизировать под cache lines</p>\n","answer":"<p><strong>Ответ:</strong> Разнести hot counters/locks, сгруппировать read-mostly поля и убрать лишние hops. Подтвердить perf c2c, cache misses и footprint на целевом CPU.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/kernel-hacking/false-sharing.html\">Linux kernel: False sharing</a></p>\n","group":"L2","line":775},{"id":"content/09_database_and_storage/02_types_of_data.md:c04582c4788e17d0:1","question":"<p>Реализовать slab allocator</p>\n","answer":"<p><strong>Ответ:</strong> Разделить память на slabs фиксированных size classes, выдавать slots через free lists/bitmap. Учитывать alignment, возврат полностью свободных slabs и metadata overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/mem.res\">C++ working draft: Memory resources</a></p>\n","group":"L2","line":781},{"id":"content/09_database_and_storage/02_types_of_data.md:fe59e48febc547ff:1","question":"<p>Реализовать NUMA-aware allocation</p>\n","answer":"<p><strong>Ответ:</strong> Использовать NUMA memory policy/first-touch с pinned workers; задать fallback при exhaustion. Проверить местоположение страниц, а не только affinity потока.</p>\n<pre><code> **Источник:** [Linux kernel: NUMA memory policy](https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L2","line":787},{"id":"content/09_database_and_storage/02_types_of_data.md:1377ff966323b5f2:1","question":"<p>Почему latency нестабилен?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить allocator, page faults, CoW snapshot, eviction, scheduler и сеть. Сопоставить p99 с событиями и оценить влияние фоновых задач при том же QPS.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/\">Redis: Latency diagnosis</a></p>\n","group":"L2","line":796},{"id":"content/09_database_and_storage/02_types_of_data.md:bb91ac9910a59bfc:1","question":"<p>Почему CPU usage высокий?</p>\n","answer":"<p><strong>Ответ:</strong> Профиль отличит полезный command processing от spins, serialization, eviction и retries. CPU utilization без completed ops/s не объясняет эффективность.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/\">Redis: Latency diagnosis</a></p>\n","group":"L2","line":802},{"id":"content/09_database_and_storage/02_types_of_data.md:267bea17111c5757:1","question":"<p>Почему malloc тормозит?</p>\n","answer":"<p><strong>Ответ:</strong> Частые мелкие allocations, общие locks и fragmentation могут доминировать. Измерить allocation rate/stacks и попробовать reuse/pool с контролем memory footprint.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/mem.res\">C++ working draft: Memory resources</a></p>\n","group":"L2","line":808},{"id":"content/09_database_and_storage/02_types_of_data.md:f85da0199a3af63f:1","question":"<p>Почему TLB misses растут?</p>\n","answer":"<p><strong>Ответ:</strong> Рабочий набор страниц вырос или доступ стал случайным. Проверить page size, NUMA и адресные patterns; huge pages могут помогать ценой fragmentation/reservation.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L2","line":814},{"id":"content/09_database_and_storage/02_types_of_data.md:1de7a0f6e0a5f80e:1","question":"<p>Как найти false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Найти contentious cache lines через perf c2c, сопоставить адреса с полями/структурами и threads. Разнести поля и подтвердить улучшение на неизменном workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/kernel-hacking/false-sharing.html\">Linux kernel: False sharing</a></p>\n","group":"L2","line":820},{"id":"content/09_database_and_storage/02_types_of_data.md:71a5e18dd5097cd8:1","question":"<p>Как устроен Redis internals?</p>\n","answer":"<p><strong>Ответ:</strong> Основной command path традиционно event-driven; словари/типы, expiration/eviction и persistence — отдельные механизмы. Версия и режим влияют на I/O threads и фоновые операции, поэтому «всё однопоточно» слишком грубо.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/\">Redis: Latency diagnosis</a>; <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a></p>\n","group":"L3","line":833},{"id":"content/09_database_and_storage/02_types_of_data.md:7f6d868fa543aa5b:1","question":"<p>Как реализуется persistence (RDB/AOF)?</p>\n","answer":"<p><strong>Ответ:</strong> RDB сохраняет снимок, AOF — журнал команд/изменений с выбранной fsync политикой и rewrite. Возможное окно потери и стоимость CoW/rewrite зависят от настройки.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/\">Redis: Latency diagnosis</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"L3","line":839},{"id":"content/09_database_and_storage/02_types_of_data.md:ed1dfdea08bbadf0:1","question":"<p>Как работает event loop?</p>\n","answer":"<p><strong>Ответ:</strong> Reactor ждёт готовности FD и вызывает handlers без блокирующей работы в loop. Долгий callback задерживает всех клиентов; CPU-heavy задачи выносят с ограничением очереди.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">Linux man-pages: epoll</a></p>\n","group":"L3","line":845},{"id":"content/09_database_and_storage/02_types_of_data.md:f0f58cd6dcb39412:1","question":"<p>Что такое zero-copy?</p>\n","answer":"<p><strong>Ответ:</strong> Исключение части копирований между слоями, например sendfile или views на mapped bytes. Не означает отсутствие всех копий и требует корректного lifetime buffers.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/mmap.2.html\">Linux man-pages: mmap</a>; <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">Linux man-pages: open</a></p>\n","group":"L3","line":851},{"id":"content/09_database_and_storage/02_types_of_data.md:dd59112eeacba784:1","question":"<p>Как работает memory eviction?</p>\n","answer":"<p><strong>Ответ:</strong> При memory limit политика выбирает кандидатов либо отклоняет запись. TTL expiration и eviction — разные механизмы; учитывать pinned/critical state и стоимость освобождения больших объектов.</p>\n<pre><code> **Источник:** [Redis: Key eviction](https://redis.io/docs/latest/develop/reference/eviction/)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L3","line":857},{"id":"content/09_database_and_storage/02_types_of_data.md:a77cebf4880df9fd:1","question":"<p>Реализовать event loop (epoll)</p>\n","answer":"<p><strong>Ответ:</strong> epoll_create1 → add nonblocking FD → epoll_wait → обработка readiness. Для edge-triggered вычитывать до EAGAIN, обрабатывать partial I/O, EOF и закрытие FD.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">Linux man-pages: epoll</a></p>\n","group":"L3","line":866},{"id":"content/09_database_and_storage/02_types_of_data.md:3815973da751d6cd:1","question":"<p>Реализовать zero-copy send</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать поддерживаемый kernel путь/ссылку на buffer, удержать ресурс до завершения отправки и обработать short write. Для TLS zero-copy зависит от конкретной реализации.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">Linux man-pages: open</a>; <a href=\"https://man7.org/linux/man-pages/man2/mmap.2.html\">Linux man-pages: mmap</a></p>\n","group":"L3","line":872},{"id":"content/09_database_and_storage/02_types_of_data.md:d3e081c12290e98f:1","question":"<p>Реализовать eviction policy</p>\n","answer":"<p><strong>Ответ:</strong> Map + LRU/LFU metadata + byte budget; evict лишь записи без активных owners/pins. Проверить bounded memory, updates и корректность при конкуренции.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a></p>\n","group":"L3","line":878},{"id":"content/09_database_and_storage/02_types_of_data.md:6ebe05ba6feab47f:1","question":"<p>Реализовать async IO</p>\n","answer":"<p><strong>Ответ:</strong> Подать операции в io_uring, связать completion с владельцем buffer, обработать short I/O/error/cancel. Completion записи не равен durable flush без нужной sync операции.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/io_uring.7.html\">Linux man-pages: io_uring</a>; <a href=\"https://man7.org/linux/man-pages/man2/fsync.2.html\">Linux man-pages: fsync</a></p>\n","group":"L3","line":884},{"id":"content/09_database_and_storage/02_types_of_data.md:cea4b1f60bd048de:1","question":"<p>Реализовать memory pool</p>\n","answer":"<p><strong>Ответ:</strong> Предвыделить blocks, хранить free slots, соблюдать alignment и общий budget. Не возвращать block, пока живы views/callbacks; добавить fallback/error при исчерпании.</p>\n<pre><code> **Источник:** [C++ working draft: Memory resources](https://eel.is/c++draft/mem.res)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L3","line":890},{"id":"content/09_database_and_storage/02_types_of_data.md:8c2232daea77b103:1","question":"<p>Почему GC/eviction вызывает latency spikes?</p>\n","answer":"<p><strong>Ответ:</strong> Освобождение больших объектов, поиск кандидатов, GC и CoW фоновых snapshots конкурируют за CPU/память. Измерить длительность и объём конкретной стадии, ограничить batch/background rate.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/\">Redis: Latency diagnosis</a>; <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a></p>\n","group":"L3","line":899},{"id":"content/09_database_and_storage/02_types_of_data.md:d123fd7854c36748:1","question":"<p>Почему network становится bottleneck?</p>\n","answer":"<p><strong>Ответ:</strong> Payload/ops × connections превысили bandwidth/packet capacity или serialization budget. Измерить bytes, retransmits, packets и server/client CPU, сравнить локальный benchmark.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":905},{"id":"content/09_database_and_storage/02_types_of_data.md:7276514f52b6dc06:1","question":"<p>Как диагностировать epoll overhead?</p>\n","answer":"<p><strong>Ответ:</strong> Смотреть calls/events, empty wakeups, batch size и loop callback time. Частое изменение interest или обработка слишком малого объёма на wakeup повышает overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">Linux man-pages: epoll</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L3","line":911},{"id":"content/09_database_and_storage/02_types_of_data.md:74e3ddbb292d6c81:1","question":"<p>Почему throughput падает при росте клиентов?</p>\n","answer":"<p><strong>Ответ:</strong> Возрастают contention, queueing, context switches и pressure общих ресурсов. Найти точку насыщения и ограничить in-flight вместо бесконечного роста clients.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"L3","line":917},{"id":"content/09_database_and_storage/02_types_of_data.md:e9b884f698222c1a:1","question":"<p>Как найти memory leak?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить live heap snapshots/alloc stacks после одинаковых циклов нагрузки и очистки. LeakSanitizer помогает на воспроизводимом сценарии; RSS сам по себе leak не доказывает.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/LeakSanitizer.html\">Clang: LeakSanitizer</a></p>\n","group":"L3","line":923},{"id":"content/09_database_and_storage/02_types_of_data.md:3ca77482b4f91974:1","question":"<p>Когда использовать in-memory DB?</p>\n","answer":"<p><strong>Ответ:</strong> Когда working set помещается в доступный RAM budget, latency оправдывает стоимость, а durability/recovery проверены. Рост данных и время загрузки тоже входят в capacity plan.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"L4","line":936},{"id":"content/09_database_and_storage/02_types_of_data.md:fe1595ca1fbedde7:1","question":"<p>Как обеспечить durability?</p>\n","answer":"<p><strong>Ответ:</strong> Durable WAL перед ACK либо синхронные устойчивые реплики по контракту, snapshots для ограниченного recovery. Проверить crash и power-loss модель; несколько volatile копий не равны диску.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a></p>\n","group":"L4","line":942},{"id":"content/09_database_and_storage/02_types_of_data.md:4beccf59412da8b9:1","question":"<p>Как проектировать hybrid RAM+disk систему?</p>\n","answer":"<p><strong>Ответ:</strong> RAM хранит горячий subset/index/cache, durable disk — источник/холодные данные. Определить eviction, promotion, freshness и p99 cold misses.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/facebook/rocksdb/wiki/RocksDB-Overview\">RocksDB: Overview</a>; <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside\">Azure Architecture: Cache-Aside</a></p>\n","group":"L4","line":948},{"id":"content/09_database_and_storage/02_types_of_data.md:7e90738e5d26b1af:1","question":"<p>Как масштабировать?</p>\n","answer":"<p><strong>Ответ:</strong> Partition key/routing и replicas, отдельная обработка hot keys и rebalance. Оценивать память, сеть и восстановление, а не только число узлов.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/reference/cluster-spec/\">Redis: Cluster specification</a>; <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"L4","line":954},{"id":"content/09_database_and_storage/02_types_of_data.md:347b01ce728c7510:1","question":"<p>Как балансировать latency vs persistence?</p>\n","answer":"<p><strong>Ответ:</strong> Задать допустимый RPO, выбрать sync/group commit/periodic mode и измерить p99. Ослабление durability должно быть частью договора, а не скрытым tuning.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"L4","line":960},{"id":"content/09_database_and_storage/02_types_of_data.md:6397b2143c9b6dc2:1","question":"<p>Что такое time-series DB?</p>\n","answer":"<p><strong>Ответ:</strong> Хранилище временных рядов с timestamp, значением и labels/tags, оптимизированное под append, time-range запросы и retention. Порядок прихода может быть неполным.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L1","line":977},{"id":"content/09_database_and_storage/02_types_of_data.md:d451a98db0dabf25:1","question":"<p>Какие особенности данных?</p>\n","answer":"<p><strong>Ответ:</strong> Много последовательных точек, временная locality, повторяющиеся tags и часто ограниченный lifecycle. High cardinality и out-of-order записи меняют память/compaction.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L1","line":983},{"id":"content/09_database_and_storage/02_types_of_data.md:6bfe4cfb5a4b79e7:1","question":"<p>Что такое append-only?</p>\n","answer":"<p><strong>Ответ:</strong> Новые записи добавляются, не переписывая существующий префикс. Логическое удаление/коррекция обычно оформляется новой записью или compaction.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/facebook/rocksdb/wiki/RocksDB-Overview\">RocksDB: Overview</a></p>\n","group":"L1","line":989},{"id":"content/09_database_and_storage/02_types_of_data.md:02a198e8a514eb0f:1","question":"<p>Что такое retention policy?</p>\n","answer":"<p><strong>Ответ:</strong> Правила удаления данных по возрасту/объёму. Учитывать ingestion lag, query windows, backup retention и реальное время освобождения blocks.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L1","line":995},{"id":"content/09_database_and_storage/02_types_of_data.md:baf158bc9a1a10a5:1","question":"<p>Что такое downsampling?</p>\n","answer":"<p><strong>Ответ:</strong> Снижение временного разрешения с агрегатами по окнам. Хранить необходимые count/sum/min/max, чтобы последующие агрегаты были корректны; среднее средних обычно неверно без весов.</p>\n<pre><code> **Источник:** [Prometheus: Storage](https://prometheus.io/docs/prometheus/latest/storage/)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L1","line":1001},{"id":"content/09_database_and_storage/02_types_of_data.md:6ae13d131691f07b:1","question":"<p>Реализовать append-only storage</p>\n","answer":"<p><strong>Ответ:</strong> Записывать framed records с timestamp/series ID/value/checksum и проверять short writes. Recovery читает корректный префикс, новый segment публикуется безопасно.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L1","line":1010},{"id":"content/09_database_and_storage/02_types_of_data.md:06e092b52852d92b:1","question":"<p>Реализовать time index</p>\n","answer":"<p><strong>Ответ:</strong> Отобразить series ID и временной диапазон в blocks, хранить sparse time index и offsets. Учитывать out-of-order data и границы [from,to).</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L1","line":1016},{"id":"content/09_database_and_storage/02_types_of_data.md:112cf0d77514eab0:1","question":"<p>Реализовать rolling window</p>\n","answer":"<p><strong>Ответ:</strong> Deque/ring для ограниченного интервала, удалять точки старше watermark по определённой политике. Уточнить event time и допустимое опоздание.</p>\n<p><strong>Источник:</strong> <a href=\"https://kafka.apache.org/41/streams/core-concepts/\">Apache Kafka Streams: Concepts</a></p>\n","group":"L1","line":1022},{"id":"content/09_database_and_storage/02_types_of_data.md:2e926d6efa237217:1","question":"<p>Реализовать retention cleanup</p>\n","answer":"<p><strong>Ответ:</strong> Удалять целые безопасно просроченные blocks после исключения активных readers и обновления manifest. Не удалять единственную копию данных, ещё нужных backup/replay.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L1","line":1028},{"id":"content/09_database_and_storage/02_types_of_data.md:ae441a16c75f4379:1","question":"<p>Реализовать timestamp compression</p>\n","answer":"<p><strong>Ответ:</strong> Кодировать разности timestamps, при регулярном шаге — delta-of-delta. Записать начальные значения/width и проверить overflow, отрицательные/нерегулярные интервалы.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L1","line":1034},{"id":"content/09_database_and_storage/02_types_of_data.md:146f9f088bbae0e2:1","question":"<p>Что такое chunking?</p>\n","answer":"<p><strong>Ответ:</strong> Разделение ряда/временного диапазона на bounded chunks с metadata и compression. Размер влияет на ingestion, памяти, pruning и число файлов.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1047},{"id":"content/09_database_and_storage/02_types_of_data.md:8dc05a7f283fcd40:1","question":"<p>Что такое compression (delta, Gorilla)?</p>\n","answer":"<p><strong>Ответ:</strong> Delta кодирует изменения времени/значений; Gorilla-подобные схемы применяют delta-of-delta timestamps и XOR floating-point представлений. Нужны точное восстановление и формат special values.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1053},{"id":"content/09_database_and_storage/02_types_of_data.md:830dfd4d0e8e15c8:1","question":"<p>Что такое cardinality problem?</p>\n","answer":"<p><strong>Ответ:</strong> Число уникальных комбинаций labels определяет число series и состояние индексов/буферов. Значения user_id/request_id могут создавать почти неограниченный рост.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a></p>\n","group":"L2","line":1059},{"id":"content/09_database_and_storage/02_types_of_data.md:04167aacc4384737:1","question":"<p>Что такое tag index?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс label name/value→series IDs, часто inverted postings. Конъюнкции пересекают IDs, затем time index выбирает нужные chunks.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1065},{"id":"content/09_database_and_storage/02_types_of_data.md:b8a09bd216e85d9c:1","question":"<p>Что такое write-heavy workload?</p>\n","answer":"<p><strong>Ответ:</strong> Поток поступления велик относительно чтения; важны batching, sequential append, partitioning, compaction capacity и backpressure. Устойчивую скорость считать вместе с maintenance.</p>\n<pre><code> **Источник:** [RocksDB: Overview](https://github.com/facebook/rocksdb/wiki/RocksDB-Overview)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L2","line":1071},{"id":"content/09_database_and_storage/02_types_of_data.md:e2d79cbf021f7390:1","question":"<p>Реализовать delta encoding</p>\n","answer":"<p><strong>Ответ:</strong> Хранить base и последовательность differences, выбрать signed/varint representation и overflow checks. Decoder должен восстанавливать исходные timestamps побитово.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1080},{"id":"content/09_database_and_storage/02_types_of_data.md:6c508790c629e20c:1","question":"<p>Реализовать chunk storage</p>\n","answer":"<p><strong>Ответ:</strong> Chunk с series/time bounds, encoded values, checksum и index entry. Закрытый chunk immutable; переключение manifest и GC должны переживать crash.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1086},{"id":"content/09_database_and_storage/02_types_of_data.md:32bf5861f0184e86:1","question":"<p>Реализовать tag index</p>\n","answer":"<p><strong>Ответ:</strong> Map label pair→sorted set series IDs, операции пересечения/объединения для query. Update/delete не должны оставлять неконтролируемый index debt.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1092},{"id":"content/09_database_and_storage/02_types_of_data.md:31546025d5725465:1","question":"<p>Реализовать compression pipeline</p>\n","answer":"<p><strong>Ответ:</strong> Последовательно применить timestamp/value encoding и общий codec, сохранить версии/параметры. Проверить round-trip на NaN/Inf/нерегулярных шагах и malformed input.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1098},{"id":"content/09_database_and_storage/02_types_of_data.md:7c81585e24c6805e:1","question":"<p>Реализовать batched ingestion</p>\n","answer":"<p><strong>Ответ:</strong> Группировать по series/partition с ограничениями bytes/time, подтверждать после durability. Сохранять event IDs/sequence и правила обработки out-of-order/retries.</p>\n<pre><code> **Источник:** [Prometheus: Storage](https://prometheus.io/docs/prometheus/latest/storage/); [AWS: Making retries safe with idempotent APIs](https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L2","line":1104},{"id":"content/09_database_and_storage/02_types_of_data.md:90aed1c89da0a259:1","question":"<p>Почему high cardinality убивает память?</p>\n","answer":"<p><strong>Ответ:</strong> Каждая новая series создаёт metadata, postings и active chunk state. Измерить series creation rate и память на series; ограничивать cardinality до приёма.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a>; <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a></p>\n","group":"L2","line":1113},{"id":"content/09_database_and_storage/02_types_of_data.md:7b1915904b9f3df4:1","question":"<p>Почему write throughput падает?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить WAL flush, compaction, число новых series, batches и hot partitions. Разделить accepted от durable persisted throughput и посмотреть queue age.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"L2","line":1119},{"id":"content/09_database_and_storage/02_types_of_data.md:43134c4aeb307a4e:1","question":"<p>Почему query latency растёт?</p>\n","answer":"<p><strong>Ответ:</strong> Больше рядов/диапазон, хуже pruning/cache или идёт compaction. По query profile измерить chunks/series/bytes examined и cardinality промежуточных результатов.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L2","line":1125},{"id":"content/09_database_and_storage/02_types_of_data.md:99ce5906a9f347ee:1","question":"<p>Почему compaction дорогой?</p>\n","answer":"<p><strong>Ответ:</strong> Слияние blocks читает/decode/reencode данные и индексы, требует временного места. Измерить pending bytes и maintenance bandwidth, не допускать неограниченного debt.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a>; <a href=\"https://github.com/facebook/rocksdb/wiki/Compaction\">RocksDB: Compaction</a></p>\n","group":"L2","line":1131},{"id":"content/09_database_and_storage/02_types_of_data.md:438521942b80901e:1","question":"<p>Почему disk IO растёт?</p>\n","answer":"<p><strong>Ответ:</strong> Рост ingestion, query scans, compaction, checkpoints и cache misses. Разложить reads/writes по компонентам и сравнить device bytes с логическими points.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L2","line":1137},{"id":"content/09_database_and_storage/02_types_of_data.md:6b87b39fded8c486:1","question":"<p>Как устроен InfluxDB / Prometheus storage?</p>\n","answer":"<p><strong>Ответ:</strong> Prometheus использует head/WAL и immutable blocks с chunk/index, но архитектура InfluxDB зависит от версии/engine. Их нельзя описывать как один одинаковый storage engine.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L3","line":1150},{"id":"content/09_database_and_storage/02_types_of_data.md:5a4b78f4b95e6550:1","question":"<p>Как работает WAL + compaction?</p>\n","answer":"<p><strong>Ответ:</strong> WAL защищает новые точки, затем flush/blocks и compaction объединяют устойчивые данные. Нужны checkpoint/retention правила, чтобы replay и disk usage оставались ограниченными.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L3","line":1156},{"id":"content/09_database_and_storage/02_types_of_data.md:ab6dc9604c0b65f4:1","question":"<p>Как реализуется compression?</p>\n","answer":"<p><strong>Ответ:</strong> По однородным временным последовательностям использовать delta/delta-of-delta/XOR, для labels — dictionary. Выигрыш измерять вместе с CPU decode/query latency.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L3","line":1162},{"id":"content/09_database_and_storage/02_types_of_data.md:923bd59d80f34451:1","question":"<p>Как устроены inverted indexes?</p>\n","answer":"<p><strong>Ответ:</strong> Термин/label value хранит postings IDs, запросы объединяют/пересекают списки. Compression, skip metadata и cardinality определяют скорость/память.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a>; <a href=\"https://www.elastic.co/docs/manage-data/data-store/mapping\">Elasticsearch: Mapping</a></p>\n","group":"L3","line":1168},{"id":"content/09_database_and_storage/02_types_of_data.md:eaa07235a82fcceb:1","question":"<p>Как работает query engine?</p>\n","answer":"<p><strong>Ответ:</strong> Планирует выбор series, time ranges/chunks, decode и aggregation. Ограничить fan-out/intermediate memory, использовать pruning и определить lookback/late data semantics.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L3","line":1174},{"id":"content/09_database_and_storage/02_types_of_data.md:fcde0e44380af2a4:1","question":"<p>Как проектировать TSDB под миллиарды точек?</p>\n","answer":"<p><strong>Ответ:</strong> Оценить points/s, активные series, bytes/point, retention и query windows. Partition по tenant/series+time, ограничить cardinality, разделить ingestion/queries и предусмотреть cold tiers.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L4","line":1187},{"id":"content/09_database_and_storage/02_types_of_data.md:cda10f67ec6bbcc9:1","question":"<p>Как решать high-cardinality проблему?</p>\n","answer":"<p><strong>Ответ:</strong> Запретить unbounded labels, задать tenant budgets, наблюдать creation churn и aggregations. Хэширование label не уменьшает число уникальных series.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a></p>\n","group":"L4","line":1193},{"id":"content/09_database_and_storage/02_types_of_data.md:8d2fca04e86bc9e7:1","question":"<p>Как строить real-time ingestion pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Устойчивый приём с ограниченной очередью, partition по series и идемпотентные batches, WAL/checkpoints и backpressure. Контролировать event age и lateness, а не только accepted rate.</p>\n<p><strong>Источник:</strong> <a href=\"https://kafka.apache.org/41/streams/core-concepts/\">Apache Kafka Streams: Concepts</a>; <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L4","line":1199},{"id":"content/09_database_and_storage/02_types_of_data.md:2d9db1b217bcc84a:1","question":"<p>Как балансировать storage vs query speed?</p>\n","answer":"<p><strong>Ответ:</strong> Настраивать chunk size, encoding, indexes и агрегаты под запросы; меньший storage может увеличивать decode CPU. Сравнить p99 и объём сканирования на реальном retention.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a></p>\n","group":"L4","line":1205},{"id":"content/09_database_and_storage/02_types_of_data.md:44db1e4103c3a8ed:1","question":"<p>Как проектировать retention + cold storage?</p>\n","answer":"<p><strong>Ответ:</strong> Горячие blocks локально, холодные — устойчивое object storage с cache и manifest/catalog. Проверить удаление/restore и запрет retention раньше завершения нужного backup/replay окна.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/prometheus/latest/storage/\">Prometheus: Storage</a>; <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html#ConsistencyModel\">Amazon S3: Consistency model</a></p>\n","group":"L4","line":1211},{"id":"content/09_database_and_storage/02_types_of_data.md:026926b1611cb1de:1","question":"<p>Что такое NewSQL?</p>\n","answer":"<p><strong>Ответ:</strong> Семейство систем с SQL/реляционными транзакциями и горизонтальной распределённостью. Термин не задаёт конкретную isolation/latency гарантию — её смотрят у продукта.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L1","line":1228},{"id":"content/09_database_and_storage/02_types_of_data.md:cfd6d3ddd477ae6b:1","question":"<p>Чем отличается от NoSQL и RDBMS?</p>\n","answer":"<p><strong>Ответ:</strong> Сохраняет SQL/транзакционную модель, распределяя хранение/координацию; NoSQL описывает другие модели доступа, традиционная RDBMS может тоже реплицироваться/шардироваться.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a>; <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"L1","line":1234},{"id":"content/09_database_and_storage/02_types_of_data.md:951a7c780803354a:1","question":"<p>Что такое distributed SQL?</p>\n","answer":"<p><strong>Ответ:</strong> SQL-план и транзакции работают над данными нескольких узлов/шардов. Требует routing, distributed execution и протоколов commit/recovery.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L1","line":1240},{"id":"content/09_database_and_storage/02_types_of_data.md:d7387e4e688afb13:1","question":"<p>Что такое strong consistency?</p>\n","answer":"<p><strong>Ответ:</strong> Нужно назвать точную модель: linearizability учитывает real time, serializability — эквивалентность последовательным транзакциям. Strong — неоднозначный общий термин.</p>\n<p><strong>Источник:</strong> <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a></p>\n","group":"L1","line":1246},{"id":"content/09_database_and_storage/02_types_of_data.md:22913d7fa136b62c:1","question":"<p>Что такое horizontal scaling?</p>\n","answer":"<p><strong>Ответ:</strong> Добавление узлов с распределением работы/данных. Глобальная координация и hot keys ограничивают масштаб даже при свободном storage.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"L1","line":1252},{"id":"content/09_database_and_storage/02_types_of_data.md:f67aa565f5035d9f:1","question":"<p>Как работает distributed transaction?</p>\n","answer":"<p><strong>Ответ:</strong> Участники согласуют commit/abort и долговечность результатов через coordinator и логи. Consensus внутри replica group не заменяет cross-shard atomic commit.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L2","line":1265},{"id":"content/09_database_and_storage/02_types_of_data.md:63bc5eb39ad9fbfb:1","question":"<p>Что такое 2PC?</p>\n","answer":"<p><strong>Ответ:</strong> Two-phase commit: prepare с durable vote, затем durable decision commit/abort и рассылка. Prepared участник может блокироваться при неизвестном исходе coordinator.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L2","line":1271},{"id":"content/09_database_and_storage/02_types_of_data.md:95a1b9a0e8fc0a2c:1","question":"<p>Что такое consensus (Raft)?</p>\n","answer":"<p><strong>Ответ:</strong> Протокол согласования журнала в группе реплик с terms, election и majority commit. Safety опирается на log/voting rules, а не только на heartbeat.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"L2","line":1277},{"id":"content/09_database_and_storage/02_types_of_data.md:3c32f12981416c45:1","question":"<p>Что такое sharding?</p>\n","answer":"<p><strong>Ответ:</strong> Разделение данных между владельцами по ключу/диапазону. Нужны карта маршрутов, репликация, migration и явные cross-shard операции.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a></p>\n","group":"L2","line":1283},{"id":"content/09_database_and_storage/02_types_of_data.md:1d15e6ea3738ac1d:1","question":"<p>Что такое global index?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс, логически охватывающий несколько shards. Обновление/уникальность требуют координации или асинхронной проекции с определёнными гарантиями.</p>\n<pre><code> **Источник:** [Google: Spanner paper](https://research.google/pubs/spanner-googles-globally-distributed-database/)\n</code></pre>\n<p><strong>[P]</strong></p>\n","group":"L2","line":1289},{"id":"content/09_database_and_storage/02_types_of_data.md:362a88c6cc4eca8c:1","question":"<p>Реализовать простой Raft (упрощённо)</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать durable term/votedFor/log, RequestVote/AppendEntries и majority commit по правилам Raft. Тестировать потерю/дубли/перестановку, restart и stale terms; не выдавать учебный прототип за production.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"L2","line":1298},{"id":"content/09_database_and_storage/02_types_of_data.md:b25fd62c7353eef7:1","question":"<p>Реализовать 2PC coordinator</p>\n","answer":"<p><strong>Ответ:</strong> Сохранять participant set и decision, prepare votes, затем commit/abort с retries. Participants сохраняют prepared state и узнают итог после restart; моделировать crash до/после каждой durable записи.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"L2","line":1304},{"id":"content/09_database_and_storage/02_types_of_data.md:74378f0d8c6c4625:1","question":"<p>Реализовать shard routing</p>\n","answer":"<p><strong>Ответ:</strong> Версионированная map key range→group, cache с epoch, redirects/retry на stale route. Во время migration должен существовать однозначный write owner.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"L2","line":1310},{"id":"content/09_database_and_storage/02_types_of_data.md:d112e545eabe8b71:1","question":"<p>Реализовать distributed KV</p>\n","answer":"<p><strong>Ответ:</strong> Локальный KV engine + replicated log + partition map + client idempotency. Сначала доказать single-shard recovery/ordering, затем membership и rebalance.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a>; <a href=\"https://github.com/facebook/rocksdb/wiki/RocksDB-Overview\">RocksDB: Overview</a></p>\n","group":"L2","line":1316},{"id":"content/09_database_and_storage/02_types_of_data.md:e7a9b96d8455ef94:1","question":"<p>Реализовать leader election</p>\n","answer":"<p><strong>Ответ:</strong> Persist term и vote, randomized election timeout, majority и проверка актуальности candidate log. После победы leader не должен подтверждать запись без нужного quorum.</p>\n<pre><code> **Источник:** [Raft paper](https://raft.github.io/raft.pdf)\n</code></pre>\n<p><strong>[D]</strong></p>\n","group":"L2","line":1322},{"id":"content/09_database_and_storage/02_types_of_data.md:30c700a225ea0cf2:1","question":"<p>Почему latency высокий?</p>\n","answer":"<p><strong>Ответ:</strong> Межузловые RTT, consensus, 2PC, remote reads и queueing добавляются к storage time. Разбить trace на эти стадии и проверить locality/leader placement.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a>; <a href=\"https://opentelemetry.io/docs/concepts/context-propagation/\">OpenTelemetry: Context propagation</a></p>\n","group":"L2","line":1331},{"id":"content/09_database_and_storage/02_types_of_data.md:cebb5fe1a5ddd70e:1","question":"<p>Почему транзакции блокируются?</p>\n","answer":"<p><strong>Ответ:</strong> Locks/conflicts либо prepared transactions ждут участников/решение commit. Проверить wait graph, intent age, coordinator state и downstream reachability.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/explicit-locking.html\">PostgreSQL: Explicit locking</a>; <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L2","line":1337},{"id":"content/09_database_and_storage/02_types_of_data.md:67f748a8e7535e23:1","question":"<p>Почему split brain?</p>\n","answer":"<p><strong>Ответ:</strong> Два writer могли действовать без общего majority/fencing или по устаревшему epoch. Сверить terms, votes, membership и ACK history; наличие heartbeat не доказывает единственность лидера.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"L2","line":1343},{"id":"content/09_database_and_storage/02_types_of_data.md:742d8db5e990efff:1","question":"<p>Почему replication lag?</p>\n","answer":"<p><strong>Ответ:</strong> Запись/передача быстрее replay из-за диска, сети, CPU, apply conflicts или тяжёлых readers. Разделить receive/flush/apply positions и измерить очередь, а не возраст последнего события.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a></p>\n","group":"L2","line":1349},{"id":"content/09_database_and_storage/02_types_of_data.md:6225f403d36e9126:1","question":"<p>Почему network — bottleneck?</p>\n","answer":"<p><strong>Ответ:</strong> Replication fanout, shuffle/joins и cross-region hops увеличивают bytes/RTT. Измерить per-link bytes, loss и queueing, затем улучшать placement/plan/batching.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"L2","line":1355},{"id":"content/09_database_and_storage/02_types_of_data.md:f5e72585106c7414:1","question":"<p>Как устроены CockroachDB / Google Spanner?</p>\n","answer":"<p><strong>Ответ:</strong> Обе — distributed SQL с replicated key ranges и транзакционным слоем, но clock/commit/isolation механизмы различаются. TrueTime относится к Spanner; детали CockroachDB нужно проверять по его версии.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L3","line":1368},{"id":"content/09_database_and_storage/02_types_of_data.md:7884d9d2fdfb8283:1","question":"<p>Что такое TrueTime?</p>\n","answer":"<p><strong>Ответ:</strong> API времени возвращает интервал возможного текущего времени с uncertainty. Spanner использует commit-wait и правила timestamps для external consistency; это не «абсолютно точные часы».</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L3","line":1374},{"id":"content/09_database_and_storage/02_types_of_data.md:b3f868bc2941652c:1","question":"<p>Как реализуется serializability?</p>\n","answer":"<p><strong>Ответ:</strong> Locking, optimistic validation либо serializable snapshot mechanisms исключают nonserializable histories. Serializable не обязательно означает real-time ordering; aborted transactions нужно безопасно повторять целиком.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/transaction-iso.html\">PostgreSQL: Transaction isolation</a>; <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L3","line":1380},{"id":"content/09_database_and_storage/02_types_of_data.md:a2b5980006835b16:1","question":"<p>Как работает distributed query planner?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирает pushdown, join order, partition pruning и обмен данными, учитывая estimates и locality. Стоимость remote shipping может доминировать над CPU/index lookup.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L3","line":1386},{"id":"content/09_database_and_storage/02_types_of_data.md:9f806d72c4be2078:1","question":"<p>Как работает rebalancing?</p>\n","answer":"<p><strong>Ответ:</strong> Копирование range/snapshot, catch-up log, безопасная смена replica membership и routing. Rate limits и placement constraints не дают переносу нарушить foreground SLO и fault tolerance.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"L3","line":1392},{"id":"content/09_database_and_storage/02_types_of_data.md:1679d3a7bc1200c6:1","question":"<p>Когда выбирать NewSQL?</p>\n","answer":"<p><strong>Ответ:</strong> Когда нужны SQL/transactions и независимый от одного узла масштаб/география, а latency/cost координации приемлемы. Сравнить с более простым replicated single-writer.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L4","line":1405},{"id":"content/09_database_and_storage/02_types_of_data.md:3d5bac57c2bef354:1","question":"<p>Как проектировать глобально распределённую БД?</p>\n","answer":"<p><strong>Ответ:</strong> Определить topology, data/leader locality, RPO/RTO и точные consistency guarantees. Согласовать residency, cross-region writes и partition degradation, затем измерить RTT и failover.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a>; <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/deployment-stamp\">Azure Architecture: Deployment stamps</a></p>\n","group":"L4","line":1411},{"id":"content/09_database_and_storage/02_types_of_data.md:a7f5fd84f38330c2:1","question":"<p>Как балансировать consistency vs latency?</p>\n","answer":"<p><strong>Ответ:</strong> По операциям выбрать инварианты и допустимую устарелость; строгие записи требуют координации, локальные проекции — reconciliation. Не ослаблять гарантию неявной маршрутизацией на follower.</p>\n<p><strong>Источник:</strong> <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a>; <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"L4","line":1417},{"id":"content/09_database_and_storage/02_types_of_data.md:860d172d1d1b6d28:1","question":"<p>Как проектировать multi-region system?</p>\n","answer":"<p><strong>Ответ:</strong> Независимые региональные стеки/группы и запас ёмкости, явный write owner/consensus, routing и проверенный failover. Учесть partition, stale metadata и recovery после возврата региона.</p>\n<p><strong>Источник:</strong> <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/deployment-stamp\">Azure Architecture: Deployment stamps</a>; <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"L4","line":1423},{"id":"content/09_database_and_storage/02_types_of_data.md:d06173a004a27a62:1","question":"<p>Как строить fault-tolerant storage?</p>\n","answer":"<p><strong>Ответ:</strong> Устойчивые replicated logs, корректный quorum, backup/restore и repair с integrity checks. Тестировать data-plane и metadata-plane отказы, не только перезапуск процесса.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a>; <a href=\"https://www.postgresql.org/docs/current/backup.html\">PostgreSQL: Backup and restore</a></p>\n","group":"L4","line":1429}];
